window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-af9c330e0a2368e7"]={"versions": [{"id": "FIG-af9c330e0a2368e7", "releases": ["R1.3.0", "R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Darstellung eines Prüfalgorithmus innerhalb der E2E-Protokollspezifikation (AUTOSAR PRS E2EProtocol). Das Diagramm spezifiziert die Prüflogik für das Prüfergebnis „Checksum OK“ (Prüfung der Datenintegrität über CRC) bei der Empfängerprüfung eines E2E-Profils.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Startknoten: Initialer Kontrollfluss mit der Beschriftung <code>Checksum OK</code>.\n</li><li>Funktionsaufruf / Aktion: Aufruf von <code>Crc_CalculateCRC8H2F()</code> mit den Parametern <code>Data[1], Data[2], … Data[Config-&gt;DataLength/8-1], DataID</code>, dessen Rückgabewert der Variablen <code>CalcualtedCRC</code> zugewiesen wird.\n</li><li>Verzweigung (Decision Node): Entscheidungsraute zur Evaluierung der Bedingung <code>CalculatedCRC == Data[0]</code>.\n</li><li>Kontrollfluss-Kanten mit Guards: Zwei ausgehende Kanten, markiert mit den Guards <code>[TRUE]</code> (linker Zweig) und <code>[FALSE]</code> (rechter Zweig).\n</li><li>Endknoten (Activity Final Nodes): Zwei Endknoten, jeweils beschriftet mit <code>return</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Die Aktivität beginnt am Initialknoten <code>Checksum OK</code>.\n</li><li>Im nachfolgenden Aktionsschritt wird die CRC-Berechnung mittels <code>Crc_CalculateCRC8H2F()</code> über die Nutzdaten ab Byte 1 bis <code>Config-&gt;DataLength/8-1</code> sowie über <code>DataID</code> ausgeführt und in <code>CalcualtedCRC</code> abgelegt.\n</li><li>An der Verzweigungsraute wird geprüft, ob die berechnete Prüfsumme mit dem an Byte-Position 0 empfangenen CRC-Wert übereinstimmt (<code>CalculatedCRC == Data[0]</code>).\n</li><li>Ergibt der Vergleich <code>[TRUE]</code>, wird der linke Pfad zum Endknoten <code>return</code> durchlaufen.\n</li><li>Ergibt der Vergleich <code>[FALSE]</code>, wird der rechte Pfad zum Endknoten <code>return</code> durchlaufen.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Spezifikation definiert das normative Verhalten bei der Integritätsprüfung empfangener Datenframes. Die Berechnung muss zwingend das angegebene CRC8H2F-Verfahren verwenden. Die berechnete Prüfsumme wird mit dem im ersten Byte (<code>Data[0]</code>) übertragenen CRC-Wert verglichen. Beide Zweige terminieren in einem <code>return</code>-Knoten; die semantische Zuordnung zu einem positiven bzw. negativen Prüfstatus ergibt sich aus den Guards <code>[TRUE]</code> und <code>[FALSE]</code>.</p>"}, {"id": "FIG-cfd2f71fd3f0c648", "releases": ["R1.5.1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Darstellung eines Prüfalgorithmus innerhalb der E2E-Protokollspezifikation (AUTOSAR PRS E2EProtocol). Das Diagramm spezifiziert die Prüflogik für das Prüfergebnis „Checksum OK“ (Prüfung der Datenintegrität über CRC) bei der Empfängerprüfung eines E2E-Profils.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Startknoten: Initialer Kontrollfluss mit der Beschriftung <code>Checksum OK</code>.\n</li><li>Funktionsaufruf / Aktion: Aufruf von <code>Crc_CalculateCRC8H2F()</code> mit den Parametern <code>Data[1], Data[2], … Data[Config-&gt;DataLength/8-1], DataID</code>, Zuweisung an <code>CalcualtedCRC</code>.\n</li><li>Verzweigung (Decision Node): Entscheidungsraute zur Evaluierung von <code>CalculatedCRC == Data [0]</code>.\n</li><li>Kontrollfluss-Kanten mit Guards: Zwei ausgehende Kanten mit <code>[TRUE]</code> (linker Zweig) und <code>[FALSE]</code> (rechter Zweig).\n</li><li>Endknoten (Activity Final Nodes): Zwei Endknoten, explizit beschriftet mit <code>return TRUE</code> (linker Zweig) und <code>return FALSE</code> (rechter Zweig).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Die Aktivität beginnt am Initialknoten <code>Checksum OK</code>.\n</li><li>Die Funktion <code>Crc_CalculateCRC8H2F()</code> berechnet die Prüfsumme über die Datenbytes <code>Data[1]</code> bis <code>Data[Config-&gt;DataLength/8-1]</code> und <code>DataID</code>; das Ergebnis wird in <code>CalcualtedCRC</code> gespeichert.\n</li><li>An der Entscheidungsraute wird die Gleichheit <code>CalculatedCRC == Data [0]</code> überprüft.\n</li><li>Bei Übereinstimmung (<code>[TRUE]</code>) wird der Kontrollfluss zum linken Endknoten geführt und <code>return TRUE</code> ausgeführt.\n</li><li>Bei Nichtübereinstimmung (<code>[FALSE]</code>) verzweigt der Kontrollfluss zum rechten Endknoten und führt <code>return FALSE</code> aus.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Spezifikation definiert normativ den booleschen Rückgabewert der Prüffunktion: Bei korrekter Prüfsumme (<code>[TRUE]</code>) gibt die Funktion <code>TRUE</code> zurück, bei abweichender Prüfsumme (<code>[FALSE]</code>) wird <code>FALSE</code> zurückgegeben. Implementierer müssen sicherstellen, dass die CRC8H2F-Berechnung exakt die spezifizierten Bytebereiche und die DataID umfasst und das Ergebnis direkt den booleschen Status der Checksummenvalidierung steuert.</p>"}, {"id": "FIG-3e687034a9127953", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Darstellung eines Prüfalgorithmus innerhalb der E2E-Protokollspezifikation (AUTOSAR PRS E2EProtocol). Das Diagramm spezifiziert die Prüflogik für das Prüfergebnis „Checksum OK“ (Prüfung der Datenintegrität über CRC) bei der Empfängerprüfung eines E2E-Profils.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Startknoten: Initialer Kontrollfluss mit der Beschriftung <code>Checksum OK</code>.\n</li><li>Funktionsaufruf / Aktion: Aufruf von <code>Crc_CalculateCRC8H2F()</code> mit den Parametern <code>Data[1], Data[2], … Data[Config-&gt;DataLength/8-1], DataID</code>, dessen Rückgabewert der Variablen <code>CalcualtedCRC</code> zugewiesen wird.\n</li><li>Verzweigung (Decision Node): Entscheidungsraute zur Evaluierung der Bedingung <code>CalculatedCRC == Data[0]</code>.\n</li><li>Kontrollfluss-Kanten mit Guards: Zwei ausgehende Kanten, markiert mit den Guards <code>[TRUE]</code> (linker Zweig) und <code>[FALSE]</code> (rechter Zweig).\n</li><li>Endknoten (Activity Final Nodes): Zwei Endknoten, jeweils beschriftet mit <code>return</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Die Aktivität beginnt am Initialknoten <code>Checksum OK</code>.\n</li><li>Im nachfolgenden Aktionsschritt wird die CRC-Berechnung mittels <code>Crc_CalculateCRC8H2F()</code> über die Nutzdaten ab Byte 1 bis <code>Config-&gt;DataLength/8-1</code> sowie über <code>DataID</code> ausgeführt und in <code>CalcualtedCRC</code> abgelegt.\n</li><li>An der Verzweigungsraute wird geprüft, ob die berechnete Prüfsumme mit dem an Byte-Position 0 empfangenen CRC-Wert übereinstimmt (<code>CalculatedCRC == Data[0]</code>).\n</li><li>Ergibt der Vergleich <code>[TRUE]</code>, wird der linke Pfad zum Endknoten <code>return</code> durchlaufen.\n</li><li>Ergibt der Vergleich <code>[FALSE]</code>, wird der rechte Pfad zum Endknoten <code>return</code> durchlaufen.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Spezifikation definiert das normative Verhalten bei der Integritätsprüfung empfangener Datenframes. Die Berechnung muss zwingend das angegebene CRC8H2F-Verfahren verwenden. Die berechnete Prüfsumme wird mit dem im ersten Byte (<code>Data[0]</code>) übertragenen CRC-Wert verglichen. Beide Zweige terminieren in einem <code>return</code>-Knoten; die semantische Zuordnung zu einem positiven bzw. negativen Prüfstatus ergibt sich aus den Guards <code>[TRUE]</code> und <code>[FALSE]</code>.</p>"}, {"id": "FIG-015646dcd4d7f7f9", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Darstellung eines Prüfalgorithmus innerhalb der E2E-Protokollspezifikation (AUTOSAR PRS E2EProtocol). Das Diagramm spezifiziert die Prüflogik für das Prüfergebnis „Checksum OK“ (Prüfung der Datenintegrität über CRC) bei der Empfängerprüfung eines E2E-Profils.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Startknoten: Initialer Kontrollfluss, beschriftet mit <code>Checksum\\nOK</code>.\n</li><li>Funktionsaufruf / Aktion: Aufruf von <code>Crc_CalculateCRC8H2F()</code> über <code>Data[1], Data[2], … Data[Config-&gt;DataLength/8-1], DataID</code> mit Zuweisung an <code>CalcualtedCRC</code>.\n</li><li>Verzweigung (Decision Node): Entscheidungsraute mit nachgestellter Bedingung <code>CalculatedCRC ==\\nData[0]</code>.\n</li><li>Kontrollfluss-Kanten mit Guards: Zwei Kanten mit <code>[TRUE]</code> (links) und <code>[FALSE]</code> (rechts).\n</li><li>Endknoten (Activity Final Nodes): Zwei Endknoten, jeweils beschriftet mit <code>return</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Die Aktivität beginnt am Initialknoten <code>Checksum OK</code>.\n</li><li>Im Aktionsknoten berechnet <code>Crc_CalculateCRC8H2F()</code> die Prüfsumme über <code>Data[1]</code> bis <code>Data[Config-&gt;DataLength/8-1]</code> unter Einbeziehung von <code>DataID</code> und weist das Resultat <code>CalcualtedCRC</code> zu.\n</li><li>An der Verzweigungsraute wird ausgewertet, ob <code>CalculatedCRC == Data[0]</code> gilt.\n</li><li>Bei positivem Vergleichsergebnis (<code>[TRUE]</code>) verzweigt der Ablauf nach links zum Endknoten <code>return</code>.\n</li><li>Bei negativem Vergleichsergebnis (<code>[FALSE]</code>) verzweigt der Ablauf nach rechts zum Endknoten <code>return</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Spezifikation definiert die normative Ablauflogik für die Checksummenprüfung. Anhand des Guards <code>[TRUE]</code> führt ein erfolgreicher CRC-Vergleich zum linken Terminierungszweig, während <code>[FALSE]</code> zum rechten Terminierungszweig führt. Beide Endknoten tragen die allgemeine Bezeichnung <code>return</code>. Implementierungen müssen den jeweiligen Ausführungspfad dem entsprechenden logischen Ergebnis der Checksummenprüfung zuweisen.</p>"}, {"id": "FIG-73ef7b137137348f", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Darstellung eines Prüfalgorithmus innerhalb der E2E-Protokollspezifikation (AUTOSAR PRS E2EProtocol). Das Diagramm spezifiziert die Prüflogik für das Prüfergebnis „Checksum OK“ (Prüfung der Datenintegrität über CRC) bei der Empfängerprüfung eines E2E-Profils.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Startknoten: Initialer Kontrollfluss, beschriftet mit <code>Checksum\\nOK</code>.\n</li><li>Funktionsaufruf / Aktion: Aufruf von <code>Crc_CalculateCRC8H2F()</code> über <code>Data[1], Data[2], … Data[Config-&gt;DataLength/8-1], DataID</code> mit Zuweisung an <code>CalcualtedCRC</code>.\n</li><li>Verzweigung (Decision Node): Entscheidungsraute mit nachgestellter Bedingung <code>CalculatedCRC ==\\nData[0]</code>.\n</li><li>Kontrollfluss-Kanten mit Guards: Zwei Kanten mit <code>[TRUE]</code> (links) und <code>[FALSE]</code> (rechts).\n</li><li>Endknoten (Activity Final Nodes): Zwei Endknoten, jeweils beschriftet mit <code>return</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Die Aktivität beginnt am Initialknoten <code>Checksum OK</code>.\n</li><li>Im Aktionsknoten berechnet <code>Crc_CalculateCRC8H2F()</code> die Prüfsumme über <code>Data[1]</code> bis <code>Data[Config-&gt;DataLength/8-1]</code> unter Einbeziehung von <code>DataID</code> und weist das Resultat <code>CalcualtedCRC</code> zu.\n</li><li>An der Verzweigungsraute wird ausgewertet, ob <code>CalculatedCRC == Data[0]</code> gilt.\n</li><li>Bei positivem Vergleichsergebnis (<code>[TRUE]</code>) verzweigt der Ablauf nach links zum Endknoten <code>return</code>.\n</li><li>Bei negativem Vergleichsergebnis (<code>[FALSE]</code>) verzweigt der Ablauf nach rechts zum Endknoten <code>return</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Spezifikation definiert die normative Ablauflogik für die Checksummenprüfung. Anhand des Guards <code>[TRUE]</code> führt ein erfolgreicher CRC-Vergleich zum linken Terminierungszweig, während <code>[FALSE]</code> zum rechten Terminierungszweig führt. Beide Endknoten tragen die allgemeine Bezeichnung <code>return</code>. Implementierungen müssen den jeweiligen Ausführungspfad dem entsprechenden logischen Ergebnis der Checksummenprüfung zuweisen.</p>"}], "trans": [{"from": "FIG-af9c330e0a2368e7", "to": "FIG-cfd2f71fd3f0c648", "fr": "R1.3.0", "tr": "R1.5.1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Untere Endknoten: Rückgabewerte explizit als <code>return TRUE</code> (linker Zweig) und <code>return FALSE</code> (rechter Zweig) beschriftet (zuvor jeweils nur unvollständig/abgeschnitten als <code>return</code>).\n</li><li>Entscheidungsraute: Beschriftung <code>CalculatedCRC == Data [0]</code> mit Leerzeichen vor <code>[0]</code> gerendert.\n</li></ul>"}, {"from": "FIG-cfd2f71fd3f0c648", "to": "FIG-af9c330e0a2368e7", "fr": "R1.5.1", "tr": "R17-10_R1.2.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Untere Endknoten: Rückgabewerte wieder auf verkürztes <code>return</code> ohne explizite Angabe von <code>TRUE</code> bzw. <code>FALSE</code> zurückgesetzt.\n</li><li>Entscheidungsraute: Beschriftung wieder als <code>CalculatedCRC == Data[0]</code> ohne Leerzeichen gerendert.\n</li></ul>"}, {"from": "FIG-af9c330e0a2368e7", "to": "FIG-3e687034a9127953", "fr": "R17-10_R1.2.0", "tr": "R18-03_R1.4.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-3e687034a9127953", "to": "FIG-cfd2f71fd3f0c648", "fr": "R18-03_R1.4.0", "tr": "R18-10_R4.4.0_R1.5.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Untere Endknoten: Rückgabewerte explizit als <code>return TRUE</code> (linker Zweig) und <code>return FALSE</code> (rechter Zweig) beschriftet (zuvor jeweils nur unvollständig/abgeschnitten als <code>return</code>).\n</li><li>Entscheidungsraute: Beschriftung <code>CalculatedCRC == Data [0]</code> mit Leerzeichen vor <code>[0]</code> gerendert.\n</li></ul>"}, {"from": "FIG-cfd2f71fd3f0c648", "to": "FIG-015646dcd4d7f7f9", "fr": "R19-03", "tr": "R19-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Untere Endknoten: Beschriftung wieder auf <code>return</code> ohne explizite Angabe von <code>TRUE</code> bzw. <code>FALSE</code> geändert.\n</li><li>Entscheidungsraute: Beschriftung <code>CalculatedCRC == Data[0]</code> ohne Leerzeichen vor dem Index formatiert und unterhalb der <code>[FALSE]</code>-Bedingung platziert.\n</li><li>Startknoten: Text <code>Checksum OK</code> zweizeilig über dem Initialknoten umgebrochen.\n</li></ul>"}, {"from": "FIG-015646dcd4d7f7f9", "to": "FIG-73ef7b137137348f", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
